-- Темы 05–08: исправлены странности в 34 вопросах (85 исправлений), прежние версии в question_archive (миграция 113), ключи не меняются.
-- Источник: scripts/questions/114_oddities_topics05_08.js
-- Повторный запуск безопасен: вопрос и вариант ищутся по тексту, прежнее или уже новое значение допустимо,
-- иначе пакет отменяется. Ключи ответов, число и порядок вариантов не меняются.

BEGIN;
SET LOCAL standard_conforming_strings = on;
LOCK TABLE questions IN SHARE ROW EXCLUSIVE MODE;

DO $fix$
DECLARE fix record; matches integer; qid integer; k text;
BEGIN
    FOR fix IN SELECT * FROM (VALUES
        ('question', 'Чем опасна долгая транзакция?', NULL, NULL, NULL, 'Транзакция на Repeatable Read держит старый снимок после обычного SELECT. Другие сеансы обновляют таблицу. Как это влияет на обслуживание базы?'),
        ('question', 'Почему откат транзакции в PostgreSQL выполняется быстро, без отмены каждого изменения?', NULL, NULL, NULL, 'Транзакция обновила много строк обычной таблицы и выполнила ROLLBACK. Почему серверу не нужно переписывать каждую изменённую версию обратно?'),
        ('question', 'С объектами каких баз может работать клиент в рамках одного подключения?', NULL, NULL, NULL, 'Клиент подключён к appdb. Из какой базы он может напрямую читать таблицы по именам схемы и таблицы? FDW и dblink не используются.'),
        ('question', 'В какую схему попадёт новая постоянная таблица, созданная без указания схемы?', NULL, NULL, NULL, 'CREATE TABLE без имени схемы успешно создала постоянную таблицу. Как сервер выбрал для неё схему?'),
        ('question', 'Допишите команду, чтобы сначала просматривалась схема app, затем public:
```
SET search_path = ___;
```', NULL, NULL, NULL, 'Допишите команду: среди явно перечисленных схем app должна стоять перед public:
```
SET search_path = ___;
```'),
        ('question', 'В таблице одна строка. Транзакция A на уровне Read Committed прочитала её. Транзакция B удалила строку и зафиксировала изменение. Сколько строк увидит A, повторив тот же запрос?', NULL, NULL, NULL, 'В таблице одна строка. Транзакция A на уровне Read Committed прочитала её. Транзакция B удалила строку и зафиксировала изменение. Каков результат повторного запроса A?'),
        ('question', 'К чему со временем приводит отключение автоочистки при регулярных изменениях данных, если не выполнять очистку и анализ вручную?', NULL, NULL, NULL, 'Какие последствия возможны при регулярных изменениях данных, если отключить обычную автоочистку и не выполнять VACUUM и ANALYZE вручную?'),
        ('question', 'Почему обращение к буферному кешу медленнее простого обращения к оперативной памяти?', NULL, NULL, NULL, 'Почему доступ к странице в общем буферном кеше требует больше действий, чем чтение локальной памяти процесса?'),
        ('question', 'Процессу нужна страница, которой нет в буферном кеше. Что он делает?', NULL, NULL, NULL, 'Обслуживающему процессу нужна существующая страница обычной журналируемой таблицы. В shared_buffers её нет, свободный буфер есть. Как процесс получит страницу?'),
        ('question', 'Страница данных сбрасывается на диск, а соответствующая ей журнальная запись ещё не записана. Что произойдёт?', NULL, NULL, NULL, 'Перед записью грязной страницы журналируемой таблицы процесс обнаружил, что соответствующий WAL ещё не сброшен на диск. fsync включён. Что процесс сделает?'),
        ('question', 'Что изменилось для схемы public начиная с PostgreSQL 15?', NULL, NULL, NULL, 'Как изменились стандартные права PUBLIC на схему public в кластере, заново созданном initdb начиная с PostgreSQL 15?'),
        ('question', 'Есть автоматически обновляемое представление CREATE VIEW active_users AS SELECT id, active FROM users WHERE active; Выполняют DELETE FROM active_users WHERE id = 7; Видимая строка с id = 7 существует, права есть, мешающих ограничений и триггеров нет. Что удалится?', NULL, NULL, NULL, 'В users есть одна строка с id = 7, у неё active = true. Создано автоматически обновляемое представление:
```
CREATE VIEW active_users AS
SELECT id, active FROM users WHERE active;
```
Права есть, мешающих ограничений и триггеров нет. Что удалит команда?
```
DELETE FROM active_users WHERE id = 7;
```'),
        ('question', 'Что такое последовательность (SEQUENCE) в PostgreSQL?', NULL, NULL, NULL, 'В базе создали последовательность order_ids. Какую задачу выполняет этот объект?'),
        ('question', 'Транзакция получила значение через nextval, а затем выполнила ROLLBACK. Будет ли это значение автоматически возвращено последовательности для повторной выдачи?', NULL, NULL, NULL, 'В psql с автофиксацией и без открытой транзакции команды ниже отправляют по одной. Первые четыре успешны, других обращений к последовательности нет. Что вернёт последний SELECT?
```
CREATE TEMP SEQUENCE order_ids START WITH 100;
BEGIN;
SELECT nextval(''order_ids'');
ROLLBACK;
SELECT nextval(''order_ids'');
```'),
        ('question', 'Что такое ограничение целостности таблицы?', NULL, NULL, NULL, 'К таблице orders с числовым столбцом total успешно добавили CHECK (total >= 0). Как это повлияет на INSERT и UPDATE?'),
        ('question', 'Транзакция A на уровне Read Committed прочитала строку. Транзакция B изменила эту строку командой UPDATE и ещё не зафиксировала изменения. A снова выполняет SELECT xmin, xmax, * FROM t. Что она увидит?', NULL, NULL, NULL, 'В t одна зафиксированная строка. A на Read Committed прочитала её обычным SELECT. B без точек сохранения обновила строку и оставила транзакцию открытой; других блокировок строки нет. A выполняет SELECT xmin, xmax, * FROM t. Что она увидит?'),
        ('question', 'В таблице t четыре строки с разной историей. Все транзакции, которые их меняли, уже завершились. Вы на Read Committed выполняете SELECT * FROM t. Какие строки вернёт запрос?', NULL, NULL, NULL, 'В исходно пустую таблицу t вставляли строки с четырьмя разными id. Каждый вариант описывает историю одной такой строки. Все указанные транзакции завершились до начала SELECT * FROM t на Read Committed. Какие из этих строк вернёт запрос?'),
        ('question', 'Таблица t (id int PRIMARY KEY, v int) без других ограничений и триггеров. Сеанс 1 выполнил BEGIN; UPDATE t SET v = 0 WHERE id = 1; и не завершил транзакцию. Каждая команда выполняется отдельно. Какие команды сеанса 2 не будут ждать блокировок сеанса 1?', NULL, NULL, NULL, 'Таблица t (id int PRIMARY KEY, v int) без других ограничений и триггеров. Сеанс 1 выполнил BEGIN; UPDATE t SET v = 0 WHERE id = 1; и не завершил транзакцию. Каждый вариант проверяют в отдельном опыте с новым сеансом 2; других сеансов и ожидающих команд нет. Какие команды сеанса 2 не будут ждать блокировок сеанса 1?'),
        ('option', 'Транзакция на Repeatable Read держит старый снимок после обычного SELECT. Другие сеансы обновляют таблицу. Как это влияет на обслуживание базы?', 'Может держать горизонт очистки, раздувая таблицы', 'VACUUM оставляет старые версии, которые ещё нужны этому снимку', 'Это происходит, если транзакция удерживает старый снимок или назначенный номер транзакции: часть старых версий ещё нельзя удалить очисткой, и таблицы и индексы разрастаются.', 'Старый снимок удерживает горизонт очистки: ещё нужные ему версии нельзя удалить, и таблицы и индексы разрастаются.'),
        ('option', 'Транзакция на Repeatable Read держит старый снимок после обычного SELECT. Другие сеансы обновляют таблицу. Как это влияет на обслуживание базы?', 'Блокирует чтение всех таблиц базы данных', 'VACUUM ждёт завершения транзакции перед очисткой всей таблицы', 'Обычные изменения строк не блокируют чтение; чтение таблицы мешает только блокировка ACCESS EXCLUSIVE.', 'VACUUM работает и удаляет уже ненужные версии; удержание горизонта не означает ожидание конца транзакции.'),
        ('option', 'Транзакция на Repeatable Read держит старый снимок после обычного SELECT. Другие сеансы обновляют таблицу. Как это влияет на обслуживание базы?', 'Останавливает запись журнала предзаписи на диск', 'Контрольная точка откладывается до COMMIT долгой транзакции', 'Запись журнала не останавливается.', 'Контрольная точка не ждёт фиксации транзакций, чтобы записать грязные страницы.'),
        ('option', 'Транзакция на Repeatable Read держит старый снимок после обычного SELECT. Другие сеансы обновляют таблицу. Как это влияет на обслуживание базы?', 'Сбрасывает накопительную статистику всего сервера', 'ANALYZE не собирает статистику прочитанной транзакцией таблицы', 'Накопительная статистика от этого не сбрасывается.', 'Обычный SELECT держит ACCESS SHARE, она совместима с блокировкой ANALYZE.'),
        ('option', 'Чем VACUUM FULL отличается от обычного VACUUM?', 'Работает без блокировок и быстрее обычной очистки таблицы', NULL, 'Наоборот: требует исключительной блокировки и работает дольше.', 'VACUUM FULL требует ACCESS EXCLUSIVE и переписывает таблицу. Сравнение длительности с обычным VACUUM зависит от объёма данных, раздувания, индексов и ресурсов системы.'),
        ('explanation', 'Как называется буфер со страницей, изменённой, но ещё не записанной на диск?', NULL, NULL, 'Запись грязных буферов на диск выполняется асинхронно и может откладываться.', 'Изменённая страница может некоторое время оставаться в памяти. Её записывают фоновые процессы, а при вытеснении это может сделать и обслуживающий процесс.'),
        ('option', 'С какого места начинается восстановление после сбоя?', 'С первого файла WAL в каталоге', 'С начала самого старого сохранившегося в pg_wal сегмента', 'Первые файлы в каталоге могут содержать старый журнал, который хранится для репликации или архива. Восстановление после сбоя начинается с позиции REDO последней завершённой контрольной точки.', 'Старые сегменты могут удерживаться для репликации или архива; начало каталога не задаёт точку восстановления.'),
        ('option', 'С какого места начинается восстановление после сбоя?', 'С последней зафиксированной транзакции', 'С записи COMMIT последней зафиксированной транзакции', 'Начинают с контрольной точки, а не с транзакции.', 'Нужно восстановить изменения страниц, а не начать с последней фиксации.'),
        ('option', 'С какого места начинается восстановление после сбоя?', 'С последней завершённой контрольной точки', 'С REDO-позиции последней завершённой контрольной точки', 'Да. Проигрывание WAL начинается с позиции REDO, указанной в записи последней завершённой контрольной точки: все изменения до этой позиции уже на диске. Это позиция начала восстановления, а не адрес самой записи о контрольной точке.', 'REDO-позиция указана в записи завершённой контрольной точки: все изменения до неё уже на диске. Она отличается от адреса самой записи о контрольной точке.'),
        ('option', 'С какого места начинается восстановление после сбоя?', 'С момента запуска сервера', 'С позиции WAL при предыдущем запуске сервера', 'Момент запуска с журналом не связан.', 'Начало определяется контрольной точкой, а не предыдущим запуском.'),
        ('explanation', 'Клиент подключён к appdb. Из какой базы он может напрямую читать таблицы по именам схемы и таблицы? FDW и dblink не используются.', NULL, NULL, 'Для работы с другой базой нужно новое подключение.', 'Обычные имена таблиц разрешаются внутри подключённой базы. Для прямого доступа к другой базе клиенту нужно другое подключение. FDW и dblink — отдельные механизмы межбазового доступа.'),
        ('option', 'Что верно для блокировок в PostgreSQL?', 'Обычные блокировки освобождаются при завершении транзакции', 'COMMIT и полный ROLLBACK освобождают обычные блокировки', NULL, NULL),
        ('option', 'Что верно для временных таблиц?', 'Не журналируются', 'Изменения данных таблицы не записываются в WAL', 'Отсутствие журнала для данных уменьшает накладные расходы на их изменение.', 'Это свойство данных временной таблицы: отсутствие журнала уменьшает накладные расходы на их изменение. Изменения её описания в системном каталоге журналируются как обычно.'),
        ('option', 'Что верно для временных таблиц?', 'Восстанавливаются после сбоя', 'Данные восстанавливаются по WAL после сбоя сервера', 'После сбоя временные таблицы не восстанавливаются.', 'Данные временных таблиц после сбоя не восстанавливаются.'),
        ('option', 'Что верно для временных таблиц?', 'Видны только создавшему их сеансу', 'Данные доступны только создавшему таблицу сеансу', 'Другие сеансы их не видят.', 'Описание объекта может быть видно в каталоге, но читать или изменять данные чужой временной таблицы нельзя.'),
        ('option', 'Что верно для временных таблиц?', 'Хранятся в общем буферном кеше', 'Страницы читаются через общий буферный кеш сервера', 'Используется локальный буферный кеш процесса.', 'Для временных таблиц используются локальные буферы обслуживающего процесса.'),
        ('explanation', 'Допишите команду: среди явно перечисленных схем app должна стоять перед public:
```
SET search_path = ___;
```', NULL, NULL, 'Схемы в search_path перечисляются через запятую в порядке просмотра.', 'Схемы в search_path перечисляются через запятую в порядке просмотра. Неявные схемы, например pg_catalog, при этом продолжают участвовать в поиске по своим правилам.'),
        ('option', 'На Repeatable Read транзакция A прочитала строку id = 1 и осталась открытой. Затем B удалила эту строку и сделала COMMIT. A повторяет тот же SELECT. Вернётся ли строка?', 'Запрос будет ждать завершения удаляющей транзакции', 'Запрос завершится ошибкой отсутствия строки', 'Обычное чтение не ждёт изменяющих транзакций; к тому же та транзакция уже завершена.', 'Обычный SELECT не выдаёт ошибку лишь из-за отсутствия строки. В этом сценарии строка к тому же остаётся видна в старом снимке A.'),
        ('option', 'В таблице одна строка. Транзакция A на уровне Read Committed прочитала её. Транзакция B удалила строку и зафиксировала изменение. Каков результат повторного запроса A?', 'Одну', 'Вернётся одна строка', 'Так будет на уровне Repeatable Read, где снимок один на всю транзакцию.', 'Первый снимок не сохраняется для следующего SELECT на этом уровне; так было бы на Repeatable Read.'),
        ('option', 'В таблице одна строка. Транзакция A на уровне Read Committed прочитала её. Транзакция B удалила строку и зафиксировала изменение. Каков результат повторного запроса A?', 'A будет ждать окончания транзакции B', 'Вернутся две версии строки', 'B уже завершена, ждать нечего; к тому же обычное чтение не ждёт изменяющих транзакций.', 'SELECT возвращает видимые строки, а не историю их физических версий.'),
        ('option', 'В таблице одна строка. Транзакция A на уровне Read Committed прочитала её. Транзакция B удалила строку и зафиксировала изменение. Каков результат повторного запроса A?', 'Ноль', 'Запрос вернёт ноль строк', 'На Read Committed снимок строится заново для каждого оператора, и удаление уже видно.', 'Новый снимок учитывает зафиксированное удаление.'),
        ('option', 'В таблице одна строка. Транзакция A на уровне Read Committed прочитала её. Транзакция B удалила строку и зафиксировала изменение. Каков результат повторного запроса A?', 'Запрос завершится ошибкой', NULL, 'Чтение на Read Committed не приводит к ошибкам сериализации.', 'Обычное повторное чтение на Read Committed не вызывает ошибку из-за зафиксированного удаления.'),
        ('option', 'Как карта видимости ускоряет доступ только по индексу?', 'Видимость на отмеченных страницах ясна без таблицы', 'Не нужно читать страницу таблицы ради видимости', NULL, NULL),
        ('option', 'Какие последствия возможны при регулярных изменениях данных, если отключить обычную автоочистку и не выполнять VACUUM и ANALYZE вручную?', 'К отключению записи изменений таблиц в журнал', 'К невозможности запустить ANALYZE отдельно от VACUUM', 'Журналирование от автоочистки не зависит.', 'Отключение автоочистки не запрещает самостоятельный ANALYZE; в условии его просто не запускают.'),
        ('option', 'Почему файл индекса B-дерева не уменьшается, даже когда очистка уже убрала ссылки на большинство записей?', 'Страницы после расщепления больше не объединяются', 'VACUUM освобождает страницы внутри файла, не укорачивая его', 'Частично заполненные страницы после расщепления не объединяются; полностью пустые используются повторно, но файл индекса не сжимается.', 'Освободившиеся страницы можно использовать повторно, а частично заполненные не объединяются; для физического уплотнения подходит REINDEX.'),
        ('option', 'Почему файл индекса B-дерева не уменьшается, даже когда очистка уже убрала ссылки на большинство записей?', 'Очистка не убирает из индексов мёртвые ссылки', 'Свободные страницы возвращаются ОС после завершения сеанса', 'По условию ссылки уже убраны, а само их удаление файл индекса не уменьшает.', 'Завершение сеанса не сокращает файл постоянного индекса.'),
        ('option', 'Почему файл индекса B-дерева не уменьшается, даже когда очистка уже убрала ссылки на большинство записей?', 'Удалённые записи переносятся в TOAST-таблицу индекса', 'Файл сокращается после следующей контрольной точки сервера', 'TOAST к индексным записям не относится.', 'Контрольная точка сохраняет изменения, но не переписывает индекс компактно.'),
        ('option', 'Почему файл индекса B-дерева не уменьшается, даже когда очистка уже убрала ссылки на большинство записей?', 'Размер индекса фиксируется при его создании', 'Следующий INSERT автоматически уплотнит индекс и сократит файл', 'Индекс растёт по мере добавления записей.', 'INSERT может занять свободное место или расширить индекс; сжатия файла он не выполняет.'),
        ('option', 'Допишите запрос, чтобы узнать суммарный размер индексов таблицы t:
```
SELECT ___(''t'');
```', '`pg_table_size`', NULL, 'Размер таблицы с её TOAST-частью, без индексов.', 'Размер таблицы со служебными слоями и TOAST-частью, включая индекс TOAST, но без индексов самой таблицы.'),
        ('option', 'Допишите запрос, чтобы узнать суммарный размер индексов таблицы t:
```
SELECT ___(''t'');
```', '`pg_indexes_size`', NULL, 'Суммирует размеры всех индексов таблицы.', 'Суммирует размеры индексов, принадлежащих самой таблице.'),
        ('option', 'Допишите команду из практики курса, чтобы выключить автоочистку (затем конфигурацию нужно перечитать):
```
ALTER SYSTEM SET autovacuum = ___;
```', '`off`', NULL, 'Логический параметр принимает on/off; в рабочей системе выключать автоочистку нельзя.', 'Логический параметр принимает on/off. В рабочей системе обычную автоочистку не следует отключать без замены регулярными VACUUM и ANALYZE; защитная очистка против переполнения XID сохраняется.'),
        ('option', 'Почему доступ к странице в общем буферном кеше требует больше действий, чем чтение локальной памяти процесса?', 'Буферы защищены блокировками для совместного доступа', 'Нужна координация доступа процессов', NULL, NULL),
        ('option', 'Обслуживающему процессу нужна существующая страница обычной журналируемой таблицы. В shared_buffers её нет, свободный буфер есть. Как процесс получит страницу?', 'Читает её через ОС в буферный кеш', 'Прочитает страницу через ОС в общий буфер PostgreSQL', 'Просит ОС прочитать страницу и помещает её в буферный кеш; ОС может прочитать её с диска или найти в собственном кеше.', 'ОС может прочитать страницу с накопителя или отдать её из своего кеша.'),
        ('option', 'Обслуживающему процессу нужна существующая страница обычной журналируемой таблицы. В shared_buffers её нет, свободный буфер есть. Как процесс получит страницу?', 'Ждёт ближайшей контрольной точки для чтения', 'Прочитает страницу в локальный буфер своего сеанса', 'Контрольная точка записывает грязные буферы и чтению не нужна.', 'Локальные буферы служат временным таблицам; здесь используется общий кеш.'),
        ('option', 'Обслуживающему процессу нужна существующая страница обычной журналируемой таблицы. В shared_buffers её нет, свободный буфер есть. Как процесс получит страницу?', 'Возвращает ошибку «страница не найдена»', 'Соберёт содержимое страницы из последних записей WAL', 'Отсутствие страницы в кеше — обычная ситуация.', 'WAL воспроизводят при восстановлении, а обычное чтение получает страницу из файла.'),
        ('option', 'Обслуживающему процессу нужна существующая страница обычной журналируемой таблицы. В shared_buffers её нет, свободный буфер есть. Как процесс получит страницу?', 'Читает её с диска напрямую, минуя ОС', 'Передаст bgwriter запрос на загрузку страницы с диска', 'PostgreSQL работает с диском через операционную систему.', 'bgwriter занимается записью грязных буферов и такие запросы на чтение не обслуживает.'),
        ('option', 'Включён асинхронный режим фиксации (synchronous_commit = off), остальные настройки по умолчанию. Чем рискует такой режим?', 'Ничем: это то же самое, что синхронный режим', NULL, 'Надёжность уменьшается, зато растёт производительность.', 'Клиент не ждёт надёжного сброса WAL при фиксации. Это может уменьшить задержку COMMIT, но допускает потерю последних подтверждённых транзакций при сбое.'),
        ('option', 'Перед записью грязной страницы журналируемой таблицы процесс обнаружил, что соответствующий WAL ещё не сброшен на диск. fsync включён. Что процесс сделает?', 'Страница запишется, а журнальная запись позже', 'Запишет страницу, отложив сброс WAL до следующего COMMIT', 'Это нарушило бы главное правило журнала предзаписи.', 'Для журналируемой страницы такой порядок нарушил бы правило предзаписи.'),
        ('option', 'Перед записью грязной страницы журналируемой таблицы процесс обнаружил, что соответствующий WAL ещё не сброшен на диск. fsync включён. Что процесс сделает?', 'Сброс страницы отложится до контрольной точки', 'Дождётся следующей контрольной точки, не записывая страницу', 'Нужная журнальная запись просто записывается немедленно.', 'Нужный WAL можно сбросить сейчас, контрольная точка для этого не нужна.'),
        ('option', 'Перед записью грязной страницы журналируемой таблицы процесс обнаружил, что соответствующий WAL ещё не сброшен на диск. fsync включён. Что процесс сделает?', 'Сервер остановится с ошибкой записи', 'Прервёт сервер из-за нарушения порядка записи', 'Это штатная ситуация.', 'Отставание сброса WAL — штатная ситуация, процесс сам обеспечивает нужный порядок.'),
        ('option', 'Перед записью грязной страницы журналируемой таблицы процесс обнаружил, что соответствующий WAL ещё не сброшен на диск. fsync включён. Что процесс сделает?', 'Журнальная запись будет сначала сброшена на диск', 'Сначала запишет WAL на устойчивый носитель', 'Журнал всегда должен попасть на диск раньше данных.', 'Перед страницей сбрасывается WAL как минимум до её LSN.'),
        ('option', 'Как изменились стандартные права PUBLIC на схему public в кластере, заново созданном initdb начиная с PostgreSQL 15?', 'У PUBLIC отозвано право CREATE по умолчанию', NULL, 'Раньше при стандартных правах создавать в ней объекты мог любой пользователь; с PostgreSQL 15 право CREATE у PUBLIC отозвано по умолчанию.', 'В новом кластере PUBLIC по умолчанию не получает CREATE на public. Обновление старого кластера не отзывает прежние права; они могут перейти в новые базы через шаблон.'),
        ('option', 'Допишите команду, чтобы создать таблицу, которая существует только в текущем сеансе:
```
CREATE ___ TABLE t (id int);
```', '`TEMP`', NULL, 'Временная таблица видна только своему сеансу и удаляется по его окончании.', 'Данные временной таблицы доступны её сеансу; по умолчанию таблица удаляется при его завершении. Описание таблицы может быть видно другим сеансам в системном каталоге.'),
        ('option', 'Что такое обычное представление (VIEW) в PostgreSQL?', 'Именованный запрос, результат которого читают как таблицу', 'Сохранённый запрос, выполняемый при каждом обращении', 'Сохраняется определение запроса; обычное представление не хранит отдельную копию результата.', 'Обычное VIEW хранит определение запроса, а не отдельную копию его результата.'),
        ('option', 'Что такое обычное представление (VIEW) в PostgreSQL?', 'Отдельная база данных внутри текущей схемы', 'Сохранённый результат запроса, обновляемый отдельной командой', 'Схема принадлежит базе; представление не создаёт вложенную базу.', 'Это описание материализованного представления.'),
        ('option', 'Что такое обычное представление (VIEW) в PostgreSQL?', 'Физическая копия таблицы, которая не обновляется', 'Таблица с данными, существующая в пределах одного сеанса', 'Обычное представление получает данные из своего запроса.', 'Это описание временной таблицы.'),
        ('option', 'Что такое обычное представление (VIEW) в PostgreSQL?', 'Индекс, обязательный для каждой таблицы', 'Подготовленный SQL-оператор, запускаемый командой EXECUTE', 'Представление и индекс — разные объекты.', 'Подготовленный оператор создаётся PREPARE; обычное VIEW используется в запросе как отношение.'),
        ('option', 'Для каких задач подходит обычное представление?', 'Заменить резервную копию исходных таблиц', 'Передавать аргументы в именованный запрос как в функцию', 'Сохранённое определение запроса не является копией данных.', 'У VIEW нет собственных параметров вызова, как у функции; для такой подпрограммы используют функцию. Сам запрос к представлению при этом может содержать параметры приложения.'),
        ('option', 'Чем материализованное представление отличается от обычного представления?', 'Создаётся как объект клиентского приложения', 'Не допускает индексов на сохранённом результате', 'Клиент может хранить копию прочитанного результата, но само материализованное представление — объект серверной базы.', 'На материализованном представлении можно создавать индексы; они ускоряют доступ к уже сохранённым строкам.'),
        ('option', 'В базе создали последовательность order_ids. Какую задачу выполняет этот объект?', 'Ограничение, запрещающее одинаковые значения во всех таблицах базы', 'Проверяет уникальность уже записанных значений столбца', 'Последовательность сама по себе не проверяет уникальность данных таблиц.', 'Уникальность данных проверяют ограничения и уникальные индексы; последовательность сама этого не делает.'),
        ('option', 'В базе создали последовательность order_ids. Какую задачу выполняет этот объект?', 'Список всех команд, выполненных одной транзакцией', 'Заполняет существующие пропуски в нумерации строк', 'Последовательность не является журналом SQL-команд.', 'Последовательность не ищет свободные номера в таблице и не устраняет пропуски.'),
        ('option', 'В базе создали последовательность order_ids. Какую задачу выполняет этот объект?', 'Обязательный порядок вывода строк любого SELECT', 'Выдаёт номер позиции строки в результате SELECT', 'Порядок результата запроса задаётся ORDER BY.', 'Номер строки результата вычисляет оконная функция; последовательность не обозначает позицию строки в выборке.'),
        ('option', 'В базе создали последовательность order_ids. Какую задачу выполняет этот объект?', 'Отдельный объект для выдачи числовых значений по заданным правилам', 'Выдаёт очередное число по настроенному шагу и границам', 'Часто последовательность используют для получения идентификаторов строк.', 'Объект хранит состояние генератора и параметры выдачи; часто его используют для идентификаторов строк.'),
        ('option', 'В psql с автофиксацией и без открытой транзакции команды ниже отправляют по одной. Первые четыре успешны, других обращений к последовательности нет. Что вернёт последний SELECT?
```
CREATE TEMP SEQUENCE order_ids START WITH 100;
BEGIN;
SELECT nextval(''order_ids'');
ROLLBACK;
SELECT nextval(''order_ids'');
```', 'Да, но после выполнения VACUUM', 'Вернёт значение 99', 'VACUUM не возвращает последовательности значения отменённых транзакций.', 'Шаг по умолчанию равен 1, а ROLLBACK не уменьшает состояние последовательности.'),
        ('option', 'В psql с автофиксацией и без открытой транзакции команды ниже отправляют по одной. Первые четыре успешны, других обращений к последовательности нет. Что вернёт последний SELECT?
```
CREATE TEMP SEQUENCE order_ids START WITH 100;
BEGIN;
SELECT nextval(''order_ids'');
ROLLBACK;
SELECT nextval(''order_ids'');
```', 'Да, состояние последовательности откатывается как таблицы', 'Вернёт значение 100', 'Для nextval действует другое правило: полученное значение не возвращается при откате.', 'Выдача 100 первым nextval не отменяется откатом.'),
        ('option', 'В psql с автофиксацией и без открытой транзакции команды ниже отправляют по одной. Первые четыре успешны, других обращений к последовательности нет. Что вернёт последний SELECT?
```
CREATE TEMP SEQUENCE order_ids START WITH 100;
BEGIN;
SELECT nextval(''order_ids'');
ROLLBACK;
SELECT nextval(''order_ids'');
```', 'Нет, потому что ROLLBACK после nextval запрещён', 'Завершится ошибкой', 'Откат разрешён; он просто не отменяет выдачу значения.', 'Последовательность создана до явной транзакции и остаётся в сеансе после её отката.'),
        ('option', 'В psql с автофиксацией и без открытой транзакции команды ниже отправляют по одной. Первые четыре успешны, других обращений к последовательности нет. Что вернёт последний SELECT?
```
CREATE TEMP SEQUENCE order_ids START WITH 100;
BEGIN;
SELECT nextval(''order_ids'');
ROLLBACK;
SELECT nextval(''order_ids'');
```', 'Нет, откат не отменяет выполненный nextval', 'Вернёт значение 101', 'Из-за этого в нумерации могут появляться пропуски.', 'После выдачи 100 следующим будет 101: откат не возвращает значение последовательности.'),
        ('option', 'К таблице orders с числовым столбцом total успешно добавили CHECK (total >= 0). Как это повлияет на INSERT и UPDATE?', 'Лимит времени выполнения любого запроса в сеансе', 'Условие будет проверять клиентский драйвер до отправки SQL', 'Время выполнения регулируется другими механизмами, например statement_timeout.', 'Ограничение проверяет сервер независимо от клиента; добавление CHECK не устанавливает код проверки в драйвер.'),
        ('option', 'К таблице orders с числовым столбцом total успешно добавили CHECK (total >= 0). Как это повлияет на INSERT и UPDATE?', 'Список ролей, которым разрешён вход в кластер', 'Нарушающие условие строки будут молча отфильтрованы', 'Это относится к доступу и аутентификации, а не к допустимости значений таблицы.', 'Нарушение CHECK вызывает ошибку, а не молчаливое исключение строки.'),
        ('option', 'К таблице orders с числовым столбцом total успешно добавили CHECK (total >= 0). Как это повлияет на INSERT и UPDATE?', 'Комментарий к таблице, который сервер не проверяет', 'Проверка новых данных начнётся после следующего ANALYZE', 'Ограничение имеет исполняемую проверку, а не только описание.', 'Проверка действует сразу после добавления ограничения; ANALYZE собирает статистику и CHECK не включает.'),
        ('option', 'К таблице orders с числовым столбцом total успешно добавили CHECK (total >= 0). Как это повлияет на INSERT и UPDATE?', 'Правило допустимости данных, проверяемое сервером', 'Сервер отклонит запись, для которой условие ложно', 'Ограничения защищают данные независимо от того, какое приложение отправило команду.', 'CHECK отвергает строку, если условие ложно; для запрета NULL отдельно задают NOT NULL.'),
        ('explanation', 'В t одна зафиксированная строка. A на Read Committed прочитала её обычным SELECT. B без точек сохранения обновила строку и оставила транзакцию открытой; других блокировок строки нет. A выполняет SELECT xmin, xmax, * FROM t. Что она увидит?', NULL, NULL, 'UPDATE транзакции B сразу записал её номер в xmax старой версии. Видна ли версия, зависит от того, зафиксирована ли эта транзакция и попала ли в снимок. По служебным полям видно, что версия ещё видна, хотя уже не актуальна. Когда B зафиксирует изменения, следующий запрос A на Read Committed увидит новую версию.', 'В заданном сценарии UPDATE записывает номер B в xmax старой версии. Пока B не завершилась, обычное чтение A видит эту старую версию. Когда B зафиксирует изменения, следующий запрос A на Read Committed увидит новую версию. В общем случае xmax может быть идентификатором MultiXact, и его нельзя всегда считать номером изменившей транзакции.'),
        ('option', 'Допишите запрос, чтобы узнать номер текущей транзакции:
```
SELECT ___;
```', '`pg_snapshot_xmin(pg_current_snapshot())`', NULL, 'Это нижняя граница снимка: самая старая транзакция, которая ещё активна.', 'Возвращает нижнюю границу данного снимка, а не номер текущей транзакции.'),
        ('explanation', 'Допишите запрос, чтобы узнать номер текущей транзакции:
```
SELECT ___;
```', NULL, NULL, 'Номер выдаётся не при BEGIN, а при первом изменении данных или при вызове pg_current_xact_id. Функция pg_current_xact_id_if_assigned вернёт NULL, если номера ещё нет. txid_current — устаревшее имя той же функции.', 'Номер выдаётся не при BEGIN, а при первом изменении данных или при вызове pg_current_xact_id. Функция pg_current_xact_id_if_assigned вернёт NULL, если номера ещё нет. txid_current — старый аналог, возвращающий bigint; pg_current_xact_id возвращает xid8.'),
        ('option', 'В исходно пустую таблицу t вставляли строки с четырьмя разными id. Каждый вариант описывает историю одной такой строки. Все указанные транзакции завершились до начала SELECT * FROM t на Read Committed. Какие из этих строк вернёт запрос?', 'Вставку отменили, удаления не было', NULL, 'Вставку откатили: версия ещё лежит на странице до очистки, но для запросов её как будто не было.', 'Вставка отменена, поэтому строка невидима. Её физическая версия может ещё оставаться до очистки.'),
        ('explanation', 'В исходно пустую таблицу t вставляли строки с четырьмя разными id. Каждый вариант описывает историю одной такой строки. Все указанные транзакции завершились до начала SELECT * FROM t на Read Committed. Какие из этих строк вернёт запрос?', NULL, NULL, 'Снимок создан после завершения всех этих транзакций. Видимость решают статусы двух транзакций: создавшей версию (xmin) и удалившей её (xmax); UPDATE для старой версии работает так же, как DELETE. Статусы сервер берёт из pg_xact (clog). Версии отменённых транзакций остаются на странице, пока их не уберёт очистка.', 'Снимок создан после завершения всех этих транзакций. Видимость решают статусы двух транзакций: создавшей версию (xmin) и удалившей её (xmax); UPDATE для старой версии работает так же, как DELETE. Статусы сервер берёт из pg_xact (clog). Версии отменённых транзакций могут оставаться на странице до очистки.'),
        ('explanation', 'Таблица t (id int PRIMARY KEY, v int) без других ограничений и триггеров. Сеанс 1 выполнил BEGIN; UPDATE t SET v = 0 WHERE id = 1; и не завершил транзакцию. Каждый вариант проверяют в отдельном опыте с новым сеансом 2; других сеансов и ожидающих команд нет. Какие команды сеанса 2 не будут ждать блокировок сеанса 1?', NULL, NULL, 'Совместимость можно проверить опытом: открыть в одном сеансе транзакцию с UPDATE, а в другом выполнить SET lock_timeout = ''2s'' и нужную команду: несовместимая команда завершится ошибкой по таймауту. Таблица совместимости режимов — в разделе Explicit Locking документации.', 'Опыт повторяют отдельно для каждой команды: в одном сеансе транзакция с UPDATE, в другом SET lock_timeout = ''2s'' и проверяемая команда; несовместимая завершится ошибкой по таймауту. Если несовместимая команда уже ждёт, последующие запросы к таблице встают в очередь за ней. Таблица совместимости режимов — в разделе Explicit Locking документации.')
    ) AS fixes(kind, question_text, opt_text, new_opt_text, old_text, new_text)
    LOOP
        -- Сначала ровно один вопрос по тексту (прежнему или новому), дальше всё только по его id.
        SELECT count(*), min(id) INTO matches, qid FROM questions
        WHERE question_text IN (fix.question_text, CASE WHEN fix.kind = 'question' THEN fix.new_text ELSE fix.question_text END);
        IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вопрос для исправления'; END IF;
        IF fix.kind = 'question' THEN
            UPDATE questions SET question_text = fix.new_text WHERE id = qid;
        ELSIF fix.kind = 'explanation' THEN
            PERFORM 1 FROM questions WHERE id = qid AND explanation IN (fix.old_text, fix.new_text);
            IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение вопроса'; END IF;
            UPDATE questions SET explanation = fix.new_text WHERE id = qid;
        ELSE
            SELECT count(*), min(o.key) INTO matches, k
            FROM questions q, jsonb_each_text(q.options) o
            WHERE q.id = qid AND o.value IN (fix.opt_text, coalesce(fix.new_opt_text, fix.opt_text));
            IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вариант ответа для исправления'; END IF;
            IF fix.new_text IS NOT NULL THEN
                PERFORM 1 FROM questions WHERE id = qid AND option_notes ->> k IN (fix.old_text, fix.new_text);
                IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение варианта'; END IF;
                UPDATE questions SET option_notes = jsonb_set(option_notes, ARRAY[k], to_jsonb(fix.new_text)) WHERE id = qid;
            END IF;
            IF fix.new_opt_text IS NOT NULL THEN
                UPDATE questions SET options = jsonb_set(options, ARRAY[k], to_jsonb(fix.new_opt_text)) WHERE id = qid;
            END IF;
        END IF;
    END LOOP;
END
$fix$;

COMMIT;
